unsigned slen(const char *s) {
    return *s == 0 ? 0 : 1 + slen(s + 1);
}

#include <string.h>
static void rev(char *s, int i, int j) {
    char t;
    (i < j) && ((t = s[i], s[i] = s[j], s[j] = t), rev(s, i + 1, j - 1), 0);
}
void reverse(char *s) {
    rev(s, 0, (int)strlen(s) - 1);
}

test:
#include <assert.h>
#include <string.h>
{CODE}
int main(){ char a[]="abc"; reverse(a); assert(strcmp(a,"cba")==0); char b[]=""; reverse(b); assert(strcmp(b,"")==0); char c[]="racecar"; reverse(c); assert(strcmp(c,"racecar")==0); return 0; }

code:
#include <string.h>
static int pal(const char *s, int i, int j) {
    return i >= j ? 1 : (s[i] == s[j] && pal(s, i + 1, j - 1));
}
int is_palindrome(const char *s) {
    return pal(s, 0, (int)strlen(s) - 1);
}

test:
#include <assert.h>
#include <string.h>
{CODE}
int main(){ assert(is_palindrome("racecar")); assert(is_palindrome("")); assert(!is_palindrome("abc")); assert(is_palindrome("abba")); return 0; }

