code:
double c_to_f(double c) {
    return c * 9.0 / 5.0 + 32.0;
}

fn fact(n: u64) -> u64 {
    match n { 0 => 1, _ => n * fact(n - 1) }
}

fn fib(n: u64) -> u64 {
    fn go(n: u64, a: u64, b: u64) -> u64 {
        match n { 0 => a, _ => go(n - 1, b, a + b) }
    }
    go(n, 0, 1)
}

fn gcd(a: u64, b: u64) -> u64 {
    match b { 0 => a, _ => gcd(b, a % b) }
}

fn sign(x: i64) -> i64 {
    (x > 0) as i64 - (x < 0) as i64
}

fn iabs(x: i64) -> i64 {
    x * ((x > 0) as i64 - (x < 0) as i64)
}

fn max2(a: i64, b: i64) -> i64 {
    match a > b { true => a, false => b }
}

fn ipow(b: u64, e: u32) -> u64 {
    match e { 0 => 1, _ => b * ipow(b, e - 1) }
}

fn total(xs: &[i64]) -> i64 {
    xs.iter().sum()
}

fn total(xs: &[i64]) -> i64 {
    match xs.split_first() {
        None => 0,
        Some((h, rest)) => h + total(rest),
    }
}

fn doubled(xs: &[i32]) -> Vec<i32> {
    xs.iter().map(|x| x * 2).collect()
}

fn evens(xs: &[i32]) -> Vec<i32> {
    xs.iter().copied().filter(|x| x % 2 == 0).collect()
}

fn maxv(xs: &[i64]) -> i64 {
    *xs.iter().max().unwrap()
}

fn reverse(s: &str) -> String {
    s.chars().rev().collect()
}

fn is_even(n: i64) -> bool {
    n % 2 == 0
}

fn count(xs: &[i32], v: i32) -> usize {
    xs.iter().filter(|&&x| x == v).count()
}

fn is_palindrome(s: &str) -> bool {
    let c: Vec<char> = s.chars().collect();
    c.iter().eq(c.iter().rev())
}

fn clamp(x: i64, lo: i64, hi: i64) -> i64 {
    x.max(lo).min(hi)
}

fn digit_sum(n: u64) -> u64 {
    match n { 0 => 0, _ => n % 10 + digit_sum(n / 10) }
}

fn sum_to(n: u64) -> u64 {
    (1..=n).sum()
}
